-- "Salas e docentes": each entry now says which class it is and when (UC, type, weekday, start–end, note).
-- Seeded with the 2026/27 room occupation of Fisiologia and the Histologia I rota (CIM), from 28 Sep onwards.
-- Histologia I slots are assumed to last two hours, like the Fisiologia timetable.
ALTER TABLE campus_spaces ADD COLUMN subject TEXT;
ALTER TABLE campus_spaces ADD COLUMN session TEXT;
ALTER TABLE campus_spaces ADD COLUMN weekday INTEGER CHECK (weekday IS NULL OR weekday BETWEEN 1 AND 7);
ALTER TABLE campus_spaces ADD COLUMN starts_at TEXT;
ALTER TABLE campus_spaces ADD COLUMN ends_at TEXT;
ALTER TABLE campus_spaces ADD COLUMN note TEXT;
-- JSON list of the Mondays (YYYY-MM-DD) of the weeks the entry applies to; NULL = every week.
ALTER TABLE campus_spaces ADD COLUMN weeks TEXT;

